<?php
if (!defined('ABSPATH')) exit;
final class Asenka_YOOtheme_Image_Guard {
 const VERSION=AYIG_VERSION; const OPTION='ayig_findings'; const LOG='ayig_audit';
 static function init(){add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_post_ayig',[__CLASS__,'action']);add_action('admin_post_ayig_view',[__CLASS__,'view']);add_action('admin_enqueue_scripts',[__CLASS__,'assets']);add_filter('admin_footer_text',[__CLASS__,'footer']);add_filter('update_footer',[__CLASS__,'footer_version'],20); if(defined('WP_CLI') && WP_CLI) self::cli();}
 static function menu(){
  add_management_page('Asenka YOOtheme Image Guard','YOOtheme Image Guard','manage_options','asenka-yootheme-image-guard',[__CLASS__,'page']);
  // Give Image Guard its own recognizable security icon in the main WP admin sidebar.
  $svg='<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 64 64"><path d="M32 5 54 13v16c0 16-9 25-22 31C19 54 10 45 10 29V13L32 5Z" fill="none" stroke="#a7aaad" stroke-width="5"/><path d="m22 32 7 7 14-16" fill="none" stroke="#a7aaad" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  add_menu_page('Asenka YOOtheme Image Guard','Image Guard','manage_options','asenka-yootheme-image-guard',[__CLASS__,'page'],'data:image/svg+xml;base64,'.base64_encode($svg),81);
 }
 static function roots(){return [WP_CONTENT_DIR.'/uploads'];}
 static function versions(){ $out=[]; foreach(wp_get_themes() as $slug=>$theme){if(stripos($slug,'yootheme')!==false || stripos($theme->get('Name'),'yootheme')!==false){$v=$theme->get('Version');$out[]=['type'=>'theme','name'=>$theme->get('Name'),'version'=>$v,'status'=>self::status($v)];}} foreach(get_plugins() as $path=>$plugin){if(stripos($path,'yootheme')!==false || stripos($plugin['Name'],'yootheme')!==false){$v=$plugin['Version'];$out[]=['type'=>'plugin','name'=>$plugin['Name'],'version'=>$v,'status'=>self::status($v)];}}return $out; }
 static function status($v){if(!preg_match('/^\d+\.\d+\.\d+/',$v))return 'unknown';return version_compare($v,'5.0.0','>=') && version_compare($v,'5.0.53','<')?'VULNERABLE':'not in known affected range';}
 static function signatures($data,$extension){$hits=[]; $rules=['php_tag'=>'/<\?(?:php|=)/i','execution'=>'/\b(?:eval|assert|shell_exec|passthru|system|proc_open|popen)\s*\(/i','obfuscation'=>'/\b(?:base64_decode|gzinflate|gzuncompress|str_rot13)\s*\(/i','request_execution'=>'/(?:\$_(?:POST|GET|REQUEST|COOKIE)\s*\[.{0,100}\]).{0,200}(?:eval|system|shell_exec)|(?:eval|system|shell_exec)\s*\(.{0,150}\$_(?:POST|GET|REQUEST|COOKIE)/is','image_polyglot'=>'/<\?(?:php|=)/i'];foreach($rules as $id=>$re){if($id==='image_polyglot' && !in_array($extension,['png','jpg','jpeg','gif','webp','avif','bmp','ico'],true))continue;if($id==='php_tag' && !in_array($extension,['png','jpg','jpeg','gif','webp','avif','bmp','ico','svg','txt','dat'],true))continue;if(preg_match($re,$data))$hits[]=$id;}return $hits;}
 static function scan(){ $findings=[];$count=0;$limit=150000; $roots=self::roots();foreach($roots as $root){if(!is_dir($root))continue;$iter=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::LEAVES_ONLY);foreach($iter as $file){if(++$count>$limit)break 2;if(!$file->isFile() || $file->isLink())continue;$path=$file->getPathname();$real=realpath($path);if(!$real || !self::within($real,$root))continue;$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$executable=in_array($ext,['php','phtml','phar','php3','php4','php5','php7','php8','pht'],true);$size=$file->getSize();$data=$size<=2097152?@file_get_contents($path):@file_get_contents($path,false,null,0,131072);if($data===false)continue;$hits=self::signatures($data,$ext);if($executable)$hits[]='executable_in_writable_area';if($executable && preg_match('~^tmp_[0-9]+\.php$~i',basename($path)))$hits[]='observed_tmp_php_pattern';if(!$hits)continue;$severity=($executable || in_array('image_polyglot',$hits,true))?'high':(in_array('request_execution',$hits,true)?'high':'review');$id=hash('sha256',$real);$findings[$id]=['id'=>$id,'path'=>$real,'size'=>$size,'mtime'=>$file->getMTime(),'sha256'=>hash_file('sha256',$real),'signals'=>array_values(array_unique($hits)),'severity'=>$severity,'state'=>'active'];}}foreach((array)get_option(self::OPTION,[]) as $old_id=>$old){if(isset($old['state']) && $old['state']!=='active') $findings[$old_id]=$old;}update_option(self::OPTION,$findings,false);self::audit('scan',count($findings).' findings; '. $count.' files visited');return ['findings'=>$findings,'visited'=>$count,'truncated'=>$count>$limit];}
 static function within($path,$root){$base=realpath($root);return $base && strncmp($path,$base.DIRECTORY_SEPARATOR,strlen($base)+1)===0;}
 static function store(){ $dir=apply_filters('ayig_quarantine_path',dirname(ABSPATH).'/asenka-yootheme-image-guard-quarantine');if(strpos(wp_normalize_path(trailingslashit($dir)),wp_normalize_path(trailingslashit(ABSPATH)))===0)throw new RuntimeException('Quarantine location must be outside the WordPress installation. Set ayig_quarantine_path to a private directory.');if(!is_dir($dir))wp_mkdir_p($dir);if(!is_dir($dir) || !is_writable($dir))throw new RuntimeException('Private quarantine directory unavailable. Configure a writable location outside webroot.');return $dir;}
 static function audit($event,$message){$log=get_option(self::LOG,[]);$log[]= ['at'=>gmdate('c'),'user'=>get_current_user_id(),'event'=>$event,'detail'=>$message];update_option(self::LOG,array_slice($log,-300),false);}
 static function mutate($id,$operation){$items=get_option(self::OPTION,[]);if(!isset($items[$id]))throw new RuntimeException('Unknown finding');$f=&$items[$id];$dir=self::store();$manifest=$dir.'/'.$id.'.json';if($operation==='quarantine'){if($f['state']!=='active')throw new RuntimeException('Not active');$path=$f['path'];if(!is_file($path)||is_link($path)||!self::allowed($path)||!hash_equals($f['sha256'],hash_file('sha256',$path)))throw new RuntimeException('File changed or unsafe');$dest=$dir.'/'.$id.'.quarantine';if(file_exists($dest))throw new RuntimeException('Quarantine collision');if(!rename($path,$dest))throw new RuntimeException('Move failed');if(file_put_contents($manifest,wp_json_encode(['original'=>$path,'sha256'=>$f['sha256']]),LOCK_EX)===false){@rename($dest,$path);throw new RuntimeException('Could not write quarantine manifest');}@chmod($dest,0600);@chmod($manifest,0600);$f['state']='quarantined';$f['quarantined_at']=time();}elseif($operation==='restore'){if($f['state']!=='quarantined')throw new RuntimeException('Not quarantined');$dest=$dir.'/'.$id.'.quarantine';if(!is_file($dest)||!hash_equals($f['sha256'],hash_file('sha256',$dest))||file_exists($f['path'])||!self::allowed($f['path']))throw new RuntimeException('Restore blocked');if(!rename($dest,$f['path']))throw new RuntimeException('Restore failed');$f['state']='active';@unlink($manifest);}elseif($operation==='delete'){if($f['state']!=='quarantined')throw new RuntimeException('Quarantine before permanent deletion');$dest=$dir.'/'.$id.'.quarantine';if(!is_file($dest)||!hash_equals($f['sha256'],hash_file('sha256',$dest)))throw new RuntimeException('Quarantined file changed');if(!unlink($dest))throw new RuntimeException('Delete failed');@unlink($manifest);$f['state']='deleted';}else throw new RuntimeException('Invalid operation');update_option(self::OPTION,$items,false);self::audit($operation,$f['path']);}
 static function allowed($path){foreach(self::roots() as $root)if(self::within($path,$root))return true;return false;}
 static function csv(){ $items=get_option(self::OPTION,[]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="asenka-yootheme-image-guard-findings-'.gmdate('Ymd-His').'.csv"');header('X-Content-Type-Options: nosniff');$o=fopen('php://output','w');fputcsv($o,['Path','Severity','State','Signals','Size','Modified UTC','SHA256']);foreach($items as $f){$path=$f['path'];if(preg_match('/^[=+@\-\t\r]/',$path))$path="'".$path;fputcsv($o,[$path,$f['severity'],$f['state'],implode('|',$f['signals']),$f['size'],gmdate('c',$f['mtime']),$f['sha256']]);}fclose($o);exit;}
 static function admin_url($tab='results'){return add_query_arg(['page'=>'asenka-yootheme-image-guard','tab'=>$tab],admin_url('admin.php'));}
 static function assets($hook){if(!in_array($hook,['tools_page_asenka-yootheme-image-guard','toplevel_page_asenka-yootheme-image-guard'],true))return;wp_enqueue_style('ayig-admin',plugins_url('assets/admin.css',AYIG_FILE),[],self::VERSION);wp_enqueue_script('ayig-admin',plugins_url('assets/admin.js',AYIG_FILE),[],self::VERSION,true);}
 static function footer($text){if(empty($_GET['page'])||sanitize_key(wp_unslash($_GET['page']))!=='asenka-yootheme-image-guard')return $text;return 'Built by <a href="https://asenka.com" target="_blank" rel="noopener noreferrer">Asenka Interactive</a> · <a href="https://github.com/Asenka-Dev-Team/Asenka-YOOtheme-Image-Guard" target="_blank" rel="noopener noreferrer">YOOtheme Image Guard on GitHub</a>';}
 static function footer_version($text){if(empty($_GET['page'])||sanitize_key(wp_unslash($_GET['page']))!=='asenka-yootheme-image-guard')return $text;return 'Image Guard v'.esc_html(self::VERSION);}
 static function definitions(){return [
 'executable_in_writable_area'=>['PHP in uploads','Executable PHP files in uploads can be remotely reachable. Not every occurrence is malicious.'],
 'observed_tmp_php_pattern'=>['Known incident naming pattern','A tmp_ followed by digits and .php in uploads; observed in the October 2026 incident, but a filename alone is not definitive.'],
 'image_polyglot'=>['PHP embedded in image','PHP opening tag detected inside a file with an image extension. Investigate possible image/PHP polyglot.'],
 'php_tag'=>['PHP marker in non-PHP file','A PHP opening tag was found in an image, text or data file.'],
 'execution'=>['Code execution function','The sample contains a PHP execution primitive such as eval, system or shell_exec. These also occur in legitimate software.'],
 'obfuscation'=>['Encoding or decompression','Code includes decoding or decompression functions often used to hide payloads. Legitimate uses exist.'],
 'request_execution'=>['Request-to-execution pattern','Request input appears near code execution, consistent with possible web-shell behavior. Manual verification required.']
 ];}
 static function priority($f){return ($f['state']==='active' && in_array('observed_tmp_php_pattern',(array)$f['signals'],true) && in_array('executable_in_writable_area',(array)$f['signals'],true));}
 static function snippet($f){if($f['state']!=='active'||!self::allowed($f['path'])||!is_file($f['path'])||is_link($f['path']))return ''; $data=@file_get_contents($f['path'],false,null,0,131072);if($data===false)return ''; $needle='/<\?(?:php|=)|\b(?:eval|base64_decode|gzinflate|shell_exec|system|passthru|assert|proc_open)\s*\(/i';if(preg_match($needle,$data,$m,PREG_OFFSET_CAPTURE)){ $offset=$m[0][1];$text=substr($data,max(0,$offset-75),360); }else $text=substr($data,0,220);return preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/','·',$text);}
 static function view(){if(!current_user_can('manage_options'))wp_die('Forbidden',403);$id=sanitize_text_field(wp_unslash($_GET['id']??''));check_admin_referer('ayig_view_'.$id);$items=get_option(self::OPTION,[]);if(!isset($items[$id]))wp_die('Finding unavailable',404);$f=$items[$id];$file=$f['state']==='quarantined'?self::store().'/'.$id.'.quarantine':$f['path'];if($f['state']==='deleted'||!is_file($file)||is_link($file)||($f['state']==='active'&&!self::allowed($file))||!hash_equals($f['sha256'],hash_file('sha256',$file)))wp_die('File is missing, changed or unsafe to view',409);$bytes=@file_get_contents($file,false,null,0,131072);if($bytes===false)wp_die('Unable to read file',500);header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');header('Cache-Control: no-store, private');header('Content-Security-Policy: default-src \'none\'; style-src \'unsafe-inline\'; sandbox');echo '<!doctype html><html><head><meta charset="utf-8"><title>Read-only file viewer</title><style>body{background:#151e25;color:#d8e6eb;font:14px system-ui;padding:24px}pre{padding:18px;background:#0b1218;white-space:pre-wrap;overflow-wrap:anywhere;border:1px solid #43515b}code{color:#8bd8e2}</style></head><body><h2>Read-only preview</h2><p><code>'.esc_html($f['path']).'</code></p><p>Showing at most 128 KiB · content escaped, never executed</p><pre>'.esc_html($bytes).'</pre></body></html>';exit;}
 static function action(){if(!current_user_can('manage_options'))wp_die('Forbidden',403);check_admin_referer('ayig');$op=sanitize_key($_POST['operation']??'');$tab=sanitize_key($_POST['tab']??'results');if(!in_array($tab,['results','quarantine','versions','updates'],true))$tab='results';try{if($op==='scan'){ $result=self::scan();$message='Scan complete: '.$result['visited'].' files examined; '.count($result['findings']).' findings'.($result['truncated']?' (limit reached)':'');}elseif($op==='export')self::csv();elseif(in_array($op,['quarantine','restore','delete'],true)){$ids=array_map('sanitize_text_field',(array)wp_unslash($_POST['ids']??[]));if(!$ids && isset($_POST['id']))$ids=[sanitize_text_field(wp_unslash($_POST['id']))];$ids=array_values(array_unique(array_filter($ids)));if(!$ids||count($ids)>200)throw new RuntimeException('Select 1–200 findings');$done=0;$errors=[];foreach($ids as $id){try{self::mutate($id,$op);$done++;}catch(Throwable $e){$errors[]=$id.': '.$e->getMessage();}}$message=ucfirst($op).' completed for '.$done.' file(s)'.($errors?'; errors: '.implode('; ',array_slice($errors,0,3)):'');}else throw new RuntimeException('Invalid operation');}catch(Throwable $e){$message=$e->getMessage();}wp_safe_redirect(add_query_arg(['notice'=>$message],self::admin_url($tab)));exit;}
 static function form($operation,$id='',$label='',$tab='results',$class=''){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="ayig-inline-form">';wp_nonce_field('ayig');echo '<input type="hidden" name="action" value="ayig"><input type="hidden" name="operation" value="'.esc_attr($operation).'"><input type="hidden" name="tab" value="'.esc_attr($tab).'"><input type="hidden" name="id" value="'.esc_attr($id).'"><button class="button ayig-action '.esc_attr($class).'" type="submit" '.($operation==='delete'?'data-confirm="Permanently delete this quarantined file? This cannot be undone."':'').'>'.esc_html($label?:ucfirst($operation)).'</button></form>';}
 static function signals_ui($f){$definitions=self::definitions();foreach((array)$f['signals'] as $sig){$d=$definitions[$sig]??[$sig,'A scanner heuristic; review the source file.'];$search='https://www.google.com/search?q='.rawurlencode('WordPress security '.$sig);echo '<details class="ayig-signal"><summary>'.esc_html(str_replace('_',' ',$sig)).'</summary><div class="ayig-pop"><strong>'.esc_html($d[0]).'</strong><p>'.esc_html($d[1]).'</p><a href="'.esc_url($search).'" target="_blank" rel="noopener noreferrer">Learn more ↗</a></div></details> ';}}
 static function rows($items,$tab){$total=0;foreach($items as $f){if($tab==='quarantine' && $f['state']!=='quarantined')continue;if($tab==='results' && $f['state']==='quarantined')continue;$total++;$priority=self::priority($f);$id=$f['id'];echo '<tr><td class="ayig-check-cell"><label><input type="checkbox" class="ayig-select" form="ayig-bulk-form" name="ids[]" value="'.esc_attr($id).'" aria-label="Select '.esc_attr(basename($f['path'])).'"></label></td><td><code class="ayig-path '.($priority?'ayig-path-priority':'').'">'.esc_html($f['path']).'</code>';if($priority)echo ' <span class="ayig-alert">Likely malicious — review</span>';if($tab==='results' && $f['state']==='active'){ $snippet=self::snippet($f);if($snippet!=='')echo '<details class="ayig-snippet"><summary>Suspect code sample</summary><pre>'.esc_html($snippet).'</pre></details>';}echo '</td><td><span class="ayig-severity ayig-severity-'.esc_attr($f['severity']).'">'.esc_html(strtoupper($f['severity'])).'</span></td><td>';self::signals_ui($f);echo '</td><td>'.esc_html(gmdate('Y-m-d H:i',intval($f['mtime']))).' UTC</td><td>'.esc_html(ucfirst($f['state'])).'</td><td class="ayig-actions">';if($f['state']!=='deleted'){ $view=wp_nonce_url(add_query_arg(['action'=>'ayig_view','id'=>$id],admin_url('admin-post.php')),'ayig_view_'.$id);echo '<a class="button ayig-action ayig-view" target="_blank" rel="noopener noreferrer" href="'.esc_url($view).'">◉ View</a>';}if($f['state']==='active')self::form('quarantine',$id,'▣ Quarantine',$tab,'ayig-warning');if($f['state']==='quarantined'){self::form('restore',$id,'↶ Restore',$tab,'ayig-success');self::form('delete',$id,'✕ Delete',$tab,'ayig-danger');}echo '</td></tr>';}if(!$total)echo '<tr><td colspan="7">No findings in this view.</td></tr>';}
 static function page(){if(!current_user_can('manage_options'))return;$tab=sanitize_key(wp_unslash($_GET['tab']??'results'));if(!in_array($tab,['results','quarantine','versions','updates'],true))$tab='results';$items=(array)get_option(self::OPTION,[]);$quarantine=count(array_filter($items,function($f){return $f['state']==='quarantined';}));echo '<div class="wrap ayig-wrap"><header class="ayig-hero"><div><p class="ayig-kicker">ASENKA SECURITY TOOLKIT</p><h1><img class="ayig-header-badge" src="' . esc_url(plugins_url('assets/security-badge.svg',AYIG_FILE)) . '" alt="" width="42" height="42"> YOOtheme Image Guard <small>v'.esc_html(self::VERSION).'</small></h1><p>Image-handler exposure checks, suspicious-file review and controlled remediation.</p></div></header>';if(isset($_GET['notice']))echo '<div class="notice notice-info"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['notice']))).'</p></div>';echo '<nav class="ayig-tabs" aria-label="Image Guard sections">';foreach(['results'=>'Scan Results','quarantine'=>'Quarantine ('.$quarantine.')','versions'=>'YOOtheme Versions','updates'=>'Updates'] as $key=>$label)echo '<a class="'.($tab===$key?'active':'').'" href="'.esc_url(self::admin_url($key)).'">'.esc_html($label).'</a>';echo '</nav>';
 if($tab==='updates'){Asenka_YOOtheme_Image_Guard_Updater::panel();}
 elseif($tab==='versions'){echo '<h2>Installed YOOtheme components</h2><table class="widefat striped"><thead><tr><th>Type</th><th>Name</th><th>Version</th><th>Assessment</th></tr></thead><tbody>';foreach(self::versions() as $v)echo '<tr><td>'.esc_html($v['type']).'</td><td>'.esc_html($v['name']).'</td><td>'.esc_html($v['version']).'</td><td>'.esc_html($v['status']).'</td></tr>';echo '</tbody></table><p>Known affected YOOtheme Pro range: 5.0.0–5.0.52. Version detection alone does not establish whether a site was compromised.</p>';}
 else {echo '<div class="ayig-toolbar">';if($tab==='results'){self::form('scan','','⟳ Scan now','results','ayig-primary');self::form('export','','↓ Export CSV','results');echo '<label class="ayig-toggle"><input type="checkbox" id="ayig-highlight" checked> Highlight high-confidence upload PHP patterns</label>';}else echo '<p>Quarantined files remain available for read-only viewing, restoration, or permanent deletion.</p>';echo '</div>';echo '<div class="ayig-bulk"><form id="ayig-bulk-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('ayig');echo '<input type="hidden" name="action" value="ayig"><input type="hidden" name="tab" value="'.esc_attr($tab).'">';echo '<div class="ayig-bulk-bar"><label><input type="checkbox" class="ayig-select-all"> Select all visible</label> <select name="operation" aria-label="Bulk action">';if($tab==='results')echo '<option value="quarantine">Quarantine selected</option>';else echo '<option value="restore">Restore selected</option><option value="delete">Permanently delete selected</option>';echo '</select> <button class="button" type="submit">Apply to selected</button> <span class="ayig-count" aria-live="polite">0 selected</span></div>';echo '</form><div class="ayig-table-scroll"><table class="widefat striped ayig-table"><thead><tr><th class="ayig-check-cell"><label><input type="checkbox" class="ayig-select-all" aria-label="Select all findings"></label></th><th>File path / evidence</th><th>Severity</th><th>Signals</th><th>Last modified</th><th>Status</th><th>Actions</th></tr></thead><tbody>';self::rows($items,$tab);echo '</tbody></table></div></form><p class="ayig-disclaimer">Only uploads are scanned. High severity is a review priority, not proof of compromise. A backup and filesystem review are recommended before modifications. Preview content is escaped and limited to 128 KiB.</p>';}
 echo '<footer class="ayig-footer"><span>© '.esc_html(gmdate('Y')).' Asenka Interactive · v'.esc_html(self::VERSION).'</span><a href="https://github.com/Asenka-Dev-Team/Asenka-YOOtheme-Image-Guard" target="_blank" rel="noopener noreferrer">GitHub repository ↗</a></footer></div>';}
 static function cli(){WP_CLI::add_command('ayig',new Asenka_YOOtheme_Image_Guard_CLI());}
}
if(defined('WP_CLI') && WP_CLI){class Asenka_YOOtheme_Image_Guard_CLI {function scan(){ $r=Asenka_YOOtheme_Image_Guard::scan();WP_CLI::success(count($r['findings']).' findings; '.$r['visited'].' files visited'.($r['truncated']?' (LIMIT REACHED)':''));}function versions(){WP_CLI\Utils\format_items('table',Asenka_YOOtheme_Image_Guard::versions(),['type','name','version','status']);}function findings($args,$assoc){$items=array_values(get_option(Asenka_YOOtheme_Image_Guard::OPTION,[]));foreach($items as &$f)$f['signals']=implode('|',$f['signals']);WP_CLI\Utils\format_items($assoc['format']??'table',$items,['id','path','severity','state','signals','sha256']);}function quarantine($args){Asenka_YOOtheme_Image_Guard::mutate($args[0]??'','quarantine');WP_CLI::success('Quarantined');}function restore($args){Asenka_YOOtheme_Image_Guard::mutate($args[0]??'','restore');WP_CLI::success('Restored');}function delete($args,$assoc){if(!isset($assoc['yes']))WP_CLI::error('Requires --yes');Asenka_YOOtheme_Image_Guard::mutate($args[0]??'','delete');WP_CLI::success('Deleted');}}}
